<?php $title='Create account';require '../includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']);$email=trim($_POST['email']);$pass=$_POST['password'];if(strlen($pass)<6){flash('Password must contain at least 6 characters.','error');}else{try{$s=$pdo->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);flash('Account created. Please login.');redirect('login.php');}catch(PDOException $e){flash('Email already registered.','error');}}} ?><section class="auth"><div class="authbox"><span class="eyebrow">JOIN SHOPNEST</span><h1>Create account</h1><form method="post"><label>Full name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="6" required></label><button class="btn primary full">Create account</button></form><p>Already registered? <a href="login.php">Login</a></p></div></section><?php require '../includes/footer.php'; ?>